).",["name"]="self",["type"]="RMAddon"},{["description"]="Stored spell ID to resolve.",["name"]="spellid",["type"]="number"},{["description"]="True to require this exact rank; false or nil follows the available rank.",["name"]="ranked",["type"]="boolean | nil"}},["bindings"]={["SpellData"]="builtin:Conditions/common.lua:SpellData"},["callName"]="addon:Widget_GetSpellId",["code"]="\010    if (WOW_PROJECT_ID ~= WOW_PROJECT_MAINLINE) then\010        if not ranked then\010            local resolved, reason = SpellData:GetSpellId(spellid)\010            return resolved, reason or (not resolved and \"spell-data-unavailable\" or nil)\010        end\010    end\010    return spellid\010",["description"]="Resolve the spell identifier stored by a condition. With exact rank enabled the supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank through the spell catalog. Returns nil and an availability reason if resolution cannot be completed.",["kind"]="function",["line"]=11,["parameters"]={"self","spellid","ranked"},["returns"]={{["description"]="Resolved spell ID, or nil when unavailable.",["type"]="number | nil"},{["description"]="Availability reason when resolution fails; nil on success.",["type"]="string | nil"}}},["Widget_SpellWidget"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Specialization scope used to resolve spell suggestions.",["name"]="spec",["type"]="number"},{["description"]="Reference input kind, such as Spec_EditBox, used for spell suggestions.",["name"]="editbox",["type"]="string"},{["description"]="Condition value record containing spell, ranked and disabled fields; updated in place.",["name"]="value",["type"]="table"},{["description"]="Resolver mapping a typed spell name to its ID.",["name"]="nametoid",["type"]="function"},{["description"]="Predicate that validates the proposed spell value.",["name"]="isvalid",["type"]="function"},{["description"]="Callback receiving the committed spell value.",["name"]="update",["type"]="function"}},["bindings"]={["SpellData"]="builtin:Conditions/common.lua:SpellData"},["callName"]="addon:Widget_SpellWidget",["code"]="\010    local spell_group = addon:CreateConditionGroup()\010    spell_group:SetLayout('RM-SpellField')\010    local rankChoice\010\010    local spell = addon:CreateSpellEditBox(editbox,value.spell)\010    local initialSpell=type(value.spell)==\"string\" and SpellData:GetSpellId(value.spell) or value.spell\010    local spellIcon = addon:CreateSpellActionIcon(spec == BOOKTYPE_PET and \"pet\" or \"spell\",initialSpell,isvalid)\010    spellIcon:SetWidth(44)\010    spellIcon:SetHeight(44)\010    spellIcon:SetText(value.spell)\010    spellIcon:SetCallback(\"OnEnterPressed\", function(_, _, v)\010        v = tonumber(v)\010        if v and isvalid(v) then\010            value.spell = v\010            spellIcon:SetText(v)\010            spell:SetText(SpellData:SpellName(value.spell, not value.ranked))\010            if GameTooltip:IsOwned(spellIcon.frame) and GameTooltip:IsVisible() then\010                GameTooltip:SetHyperlink(\"spell:\" .. v)\010            end\010        else\010            value.spell = nil\010            spellIcon:SetText(nil)\010            spell:SetText(nil)\010            if GameTooltip:IsOwned(spellIcon.frame) and GameTooltip:IsVisible() then\010                GameTooltip:Hide()\010            end\010        end\010        update()\010    end)\010    spellIcon:SetCallback(\"OnEnter\", function()\010        if value.spell then\010            GameTooltip:SetOwner(spellIcon.frame, \"ANCHOR_BOTTOMRIGHT\", 3)\010            GameTooltip:SetHyperlink(\"spell:\" .. value.spell)\010        end\010    end)\010    spellIcon:SetCallback(\"OnLeave\", function()\010        if GameTooltip:IsOwned(spellIcon.frame) then\010            GameTooltip:Hide()\010        end\010    end)\010    spellIcon:SetDisabled(value.disabled)\010    spell_group:AddChild(spellIcon)\010\010    if WOW_PROJECT_ID ~= WOW_PROJECT_MAINLINE and spec ~= BOOKTYPE_PET then\010        local nr_button = addon:CreateConditionCheckBox()\010        nr_button:SetLabel(L[\"Use this exact spell rank\"])\010        nr_button:SetValue(value.ranked or false)\010        nr_button:SetCallback(\"OnValueChanged\", function(_, _, val)\010            value.ranked = val\010            spell:SetUserData(\"norank\", not val)\010            spell:SetText(value.spell and SpellData:SpellName(value.spell, not value.ranked))\010            update()\010        end)\010        nr_button:SetDisabled(value.disabled)\010        rankChoice=nr_button\010    end\010\010    spell:SetFullWidth(true)\010    spell:SetLabel('')\010    spell:SetText(value.spell and SpellData:SpellName(value.spell, not value.ranked))\010    spell:SetUserData(\"norank\", not value.ranked)\010    spell:SetUserData(\"spec\", spec)\010    spell:SetCallback(\"OnEnterPressed\", function(_, _, v)\010        if not addon.isint(v) then\010            v = nametoid(v)\010        else\010            v = tonumber(v)\010        end\010        if isvalid(v) then\010            value.spell = v\010            spell:SetText(SpellData:SpellName(value.spell, not value.ranked))\010        else\010            value.spell = nil\010            spell:SetText(nil)\010        end\010        spellIcon:SetText(value.spell)\010        update()\010    end)\010    spell:SetDisabled(value.disabled)\010    spell_group:AddChild(spell)\010    if rankChoice then\010        rankChoice.frame.GetFontString=function() return rankChoice.button:GetFontString() end\010        spell_group:AddChild(rankChoice)\010    end\010\010    return spell_group\010",["description"]="Create a spell input with suggestions, validation and spell-link support for custom condition widgets. The update callback owns saving a chosen value; add the returned widget to the callback parent.",["kind"]="function",["line"]=37,["parameters"]={"self","sp