d.name==target.name\010                if not matches and record.name==\"\" then\010                    local info,issue\010                    if record.spellID then info,issue=observe(cache,platform.GetSpellInfo,record.spellID) end\010                    if info then matches=info.name==target.name\010                    else unavailable=unavailable or issue or \"totem-identity-unavailable\" end\010                end\010            end\010            if matches and (not compareTime or addon.compare(value.operator,addon.round(remaining(record,start),3),value.value)) then return true end\010        end\010    end\010    if unavailable then return nil,unavailable end\010    return false\010",["kind"]="function",["line"]=43,["parameters"]={"value","cache","start","compareTime"}},["helpers"]={["kind"]="value"},["observe"]={["bindings"]={["platform"]="builtin:Conditions/totem.lua:platform"},["code"]="\010    return addon.getCached(cache,method,platform,...)\010",["kind"]="function",["line"]=26,["parameters"]={"cache","method","..."}},["platform"]={["kind"]="value"},["remaining"]={["bindings"]={},["code"]="\010    if not record.active then return 0 end\010    return math.max(0,record.startTime+record.duration-(start or GetTime()))\010",["kind"]="function",["line"]=29,["parameters"]={"record","start"}},["specific"]={["bindings"]={},["code"]="\010    return addon.IsConditionSpellID(value.spell) and (value.ranked==nil or type(value.ranked)==\"boolean\")\010",["kind"]="function",["line"]=40,["parameters"]={"value"}}},["hash"]="8d46741799b4868b80774c3fd83824d4dacba3d587a8f4bd1f56c777f46a537c"},["Conditions/weapon.lua"]={["bindings"]={["color"]={["kind"]="value"},["enchantObservation"]={["bindings"]={},["code"]="\010    if type(GetWeaponEnchantInfo)~=\"function\" then return nil,nil,nil,\"missing-api\" end\010    -- The protected cached API returns both hands' original tuple unchanged.\010    ---@diagnostic disable-next-line: unbalanced-assignments\010    local ok, main, mainE