="utils"},["cacheMisses"]={["bindingID"]="builtin:utils.lua:cacheMisses",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["cachedResult"]={["bindingID"]="builtin:utils.lua:cachedResult",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["getCached"]={["args"]={{["description"]="Evaluation cache, or nil to bypass caching.",["name"]="cache",["type"]="table | nil"},{["description"]="Function or global function name to call.",["name"]="func",["type"]="function | string"},{["description"]="Arguments forwarded unchanged; types, identity, arity and nil positions distinguish cache entries.",["name"]="...",["type"]="any"}},["bindingID"]="builtin:utils.lua:getCached",["bindings"]={["getCachedInternal"]="builtin:utils.lua:getCachedInternal"},["callName"]="Functions.cache.getCached",["code"]="\010    return getCachedInternal(cache, true, func, ...)\010",["compatibilityNamespaces"]={"utils"},["description"]="Call an observation once per cache and exact argument tuple, including nil results. Pass the evaluation cache to share observations within a recommendation cycle; nil cache calls directly.",["kind"]="function",["line"]=75,["namespace"]="Functions.cache",["parameters"]={"cache","func","..."},["returns"]={{["description"]="All original results, preserving nil positions and return count.",["type"]="..."}}},["getCachedInternal"]={["bindingID"]="builtin:utils.lua:getCachedInternal",["bindings"]={["_G"]="builtin:utils.lua:_G",["cacheHits"]="builtin:utils.lua:cacheHits",["cacheMisses"]="builtin:utils.lua:cacheMisses",["cachedResult"]="builtin:utils.lua:cachedResult",["nilArgument"]="builtin:utils.lua:nilArgument",["packResults"]="builtin:utils.lua:packResults"},["code"]="\010    if type(func) == 'string' then func = _G[func] end\010    if type(func) ~= 'function' then return end\010    if cache == nil then return func(...) end\010\010    -- Exact keys preserve argument types, identity and arity. Hashing concatenated\010    -- strings allowed unrelated observations to collide, even for numeric IDs.\010    local args, count = { ... }, select('#', ...)\010    for i = 1, count do\010        local value = args[i]\010        if addon.Platform and addon.Platform.CanReadValue and not addon.Platform:CanReadValue(value) then\010            return func(...)\010        end\010        if type(value) == 'number' and value ~= value then return func(...) end\010        if value == nil then args[i] = nilArgument end\010    end\010    local node = cache[func]\010    for i = 1, count do\010        if not node then break end\010        node = node[args[i]]\010    end\010    local result = node and node[cachedResult]\010    if result then\010        cacheHits = cacheHits + 1\010        return unpack(result, 1, result.n)\010    end\010\010    cacheMisses = cacheMisses + 1\010    result = packResults(func(...))\010    local store = recordnil\010    if not store then\010        -- Inspect the packed keys, not potentially restricted return values.\010        for key in pairs(result) do\010            if type(key) == 'number' then store = true; break end\010        end\010    end\010    if store then\010        -- Retry misses and thrown calls must not accumulate empty paths.\010        if not cache[func] then cache[func] = {} end\010        node = cache[func]\010        for i = 1, count do\010            local key = args[i]\010            if not node[key] then node[key] = {} end\010            node = node[key]\010        end\010        node[cachedResult] = result\010    end\010    return unpack(result, 1, result.n)\010",["description"]="Packaged helper from utils.lua.",["kind"]="function",["line"]=25,["namespace"]="utils",["parameters"]={"cache","recordnil","func","..."}},["getRetryCached"]={["args"]={{["description"]="Evaluation cache, or nil to bypass caching.",["name"]="cache",["type"]="table | nil"},{["description"]="Function or global function name to call.",["name"]="func",["type"]="function | string"},{["description"]="Arguments forwarded unchanged to the observed function.",["name"]="...",["type"]="any"}},["bindingID"]="builtin:utils.lua:getRetryCached",["bindings"]={["getCachedInternal"]="builtin:utils.lua:getCachedInternal"},["callName"]="Functions.cache.getRetryCached",["code"]="\010    return getCachedInternal(cache, false, func, ...)\010",["compatibilityNamespaces"]={"utils"},["description"]="Cache an observation after it returns a non-nil value; retry observations whose entire return tuple is nil. Uses the same exact argument keys as getCached.",["kind"]="function",["line"]=79,["namespace"]="Functions.cache",["parameters"]={"cache","func","..."},["returns"]={{["description"]="All original results, preserving nil positions and return count.",["type"]="..."}}},["nilArgument"]={["bindingID"]="builtin:utils.lua:nilArgument",["description"]="Packaged helper from utils.lua.",["kind"]="value",["namespace"]="utils"},["packResults"]={["bindingID"]="builtin:utils.lua:packResults",["bindings"]={},["code"]="\010    return { n = select('#', ...), ... }\010",["description"]="Packaged helper from utils.lua.",["kind"]="function",["line"]=21,["namespace"]="utils",["parameters"]={"..."}},["protectedRead"]={["bindingID"]="builtin:Conditions/spatial.lua:protectedRead",["bindings"]={},["code"]="\010    if type(method)~=\"function\" then return false,\"missing-api\" end\010    return pcall(addon.getCached,cache,method,...)\010",["description"]="Packaged helper from Conditions/spatial.lua.",["kind"]="function",["line"]=4,["namespace"]="Conditions.spatial",["parameters"]={"cache","method","..."}}},["hash"]="75b13ab5ebf715adf2c7ce60977d5ad31321ecb83375817211c03b65533363cb"},["Functions/collections.lua"]={["bindings"]={["cleanArray"]={["args"]={{["description"]="Table to modify, or nil to do nothing.",["name"]="array",["type"]="table | nil"},{["description"]="Optional collection of key values selecting entries; its own keys are ignored.",["name"]="except",["type"]="table | nil"},{["description"]="True removes listed entries; false or nil preserves only listed entries.",["name"]="invert",["type"]="boolean | nil"}},["bindings"]={},["callName"]="Functions.collections.cleanArray",["code"]="\010    if array == nil then\010        return\010    end\010    if invert == nil then\010        invert = false\010    end\010\010    for k,_ in pairs(array) do\010        local skip = invert\010        if except ~= nil then\010            for _,v2 in pairs(except) do\010                if (k == v2) then\010                    skip = not invert\010                    break\010                end\010            end\010        end\010        if not skip then\010            array[k] = nil\010        end\010    end\010",["description"]="Remove entries in place, preserving only keys listed among except values by default. With invert true, remove listed keys and retain unlisted keys. Without an exception list, the default removes every entry and invert true retains every entry. Nil input does nothing.",["kind"]="function",["line"]=73,["parameters"]={"array","except","invert"},["returns"]={{["description"]="No return values. The supplied table is modified in place.",["type"]="..."}}},["compareArray"]={["args"]={{["description"]="First table to compare.",["name"]="lhs",["type"]="table"},{["description"]="Second table to compare.",["name"]="rhs",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.compareArray",["code"]="\010    for k,v in pairs(lhs) do\010        if rhs[k] ~= v then\010            return false\010        end\010    end\010    for k,v in pairs(rhs) do\010        if lhs[k] ~= v then\010            return false\010        end\010    end\010    return true\010",["description"]="Visit entries in both tables and compare each value with the indexed value in the other table using Lua equality. Normal indexing and equality metamethods apply; nested contents are not compared recursively.",["kind"]="function",["line"]=123,["parameters"]={"lhs","rhs"},["returns"]={{["description"]="True when every visited entry compares equal in both directions.",["type"]="boolean"}}},["deepcopy"]={["args"]={{["description"]="Table to copy shallowly, or nil.",["name"]="array",["type"]="table | nil"},{["description"]="Optional collection of key values selecting entries; its own keys are ignored.",["name"]="except",["type"]="table | nil"},{["description"]="True includes only listed entries; false or nil excludes listed entries.",["name"]="invert",["type"]="boolean | nil"}},["bindings"]={},["callName"]="Functions.collections.deepcopy",["code"]="\010    if array == nil then\010        return nil\010    end\010    if invert == nil then\010        invert = false\010    end\010\010    local rv = {}\010    for k,v in pairs(array) do\010        local skip = invert\010        if except ~= nil then\010            for _,v2 in pairs(except) do\010                if (k == v2) then\010                    skip = not invert\010                    break\010                end\010            end\010        end\010        if not skip then\010            rv[k] = v\010        end\010    end\010    return rv\010",["description"]="Create a shallow filtered copy despite the historical deepcopy name. Nested values retain their original identities and the source metatable is not copied. By default exclude keys listed among except values; invert true includes only listed keys. Nil input returns nil.",["kind"]="function",["line"]=97,["parameters"]={"array","except","invert"},["returns"]={{["description"]="New shallow filtered table, or nil for nil input.",["type"]="table | nil"}}},["index"]={["args"]={{["description"]="Table to search; nil or false returns nil.",["name"]="array",["type"]="table | nil | false"},{["description"]="Value compared with each table value using Lua equality.",["name"]="value",["type"]="any"}},["bindings"]={},["callName"]="Functions.collections.index",["code"]="\010    if not array then return nil end\010\010    for idx,v in pairs(array) do\010        if (v == value) then\010            return idx\010        end\010    end\010",["description"]="Return the first key whose value equals the supplied value during pairs traversal. Nil or false input tables and absent values return nil. Multiple matching keys have no guaranteed selection order.",["kind"]="function",["line"]=50,["parameters"]={"array","value"},["returns"]={{["description"]="Matching key, including a false key, or nil when no match exists.",["type"]="any"}}},["keys"]={["args"]={{["description"]="Table whose values must be mutually comparable.",["name"]="array",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.keys",["code"]="\010    local rv = {}\010    for k,_ in pairs(array) do\010        table.insert(rv, k)\010    end\010    -- Sort the keys\010    table.sort(rv, function (lhs, rhs) return array[lhs] < array[rhs] end)\010    return rv\010",["description"]="Collect table keys and sort them by their associated values using Lua less-than comparison. This sorts values rather than key names; equal values have no guaranteed key order.",["kind"]="function",["line"]=9,["parameters"]={"array"},["returns"]={{["description"]="Dense array of keys sorted by associated value.",["type"]="table"}}},["multiinsert"]={["args"]={{["description"]="Destination array modified in place.",["name"]="t",["type"]="table"},{["description"]="Source array whose ipairs prefix is inserted without copying nested values.",["name"]="values",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.multiinsert",["code"]="\010    for i,v in ipairs(values) do\010\009    table.insert(t, i, v)\010    end\010",["description"]="Insert each value visited by ipairs at its corresponding leading index in the destination array. Existing entries shift after the inserted prefix; traversal stops at the first missing source index.",["kind"]="function",["line"]=67,["parameters"]={"t","values"},["returns"]={{["description"]="No return values. The destination array is modified in place.",["type"]="..."}}},["spairs"]={["args"]={{["description"]="Table to traverse; keys must be mutually comparable when no custom ordering is supplied.",["name"]="t",["type"]="table"},{["description"]="Optional ordering callback called as order(t, leftKey, rightKey).",["name"]="order",["type"]="function | nil"}},["bindings"]={},["callName"]="Functions.collections.spairs",["code"]="\010    -- collect the keys\010    local keys = {}\010    for k in pairs(t) do keys[#keys+1] = k end\010\010    -- if order function given, sort by it by passing the table and keys a, b,\010    -- otherwise just sort the keys\010    if order then\010        table.sort(keys, function(a,b) return order(t, a, b) end)\010    else\010        table.sort(keys)\010    end\010\010    -- return the iterator function\010    local i = 0\010    return function()\010        i = i + 1\010        if keys[i] then\010            return keys[i], t[keys[i]]\010        end\010    end\010",["description"]="Create an iterator over a sorted snapshot of table keys. Default ordering compares keys; a custom order callback receives the original table and two keys. Values are read from the original table when each key is yielded. The legacy iterator ends when the next captured key is nil or false.",["kind"]="function",["line"]=19,["parameters"]={"t","order"},["returns"]={{["description"]="Iterator yielding a captured key and its current table value, or no values when exhausted.",["type"]="function"}}},["tablelength"]={["args"]={{["description"]="Table to count, or nil for zero.",["name"]="T",["type"]="table | nil"}},["bindings"]={},["callName"]="Functions.collections.tablelength",["code"]="\010    if T == nil then return 0 end\010    local count = 0\010    for _ in pairs(T) do count = count + 1 end\010    return count\010",["description"]="Count all entries visited by pairs, including false values and sparse numeric or nonnumeric keys. A nil table has length zero.",["kind"]="function",["line"]=60,["parameters"]={"T"},["returns"]={{["description"]="Number of entries visited.",["type"]="number"}}},["tomap"]={["args"]={{["description"]="Table whose keys should be converted to strings.",["name"]="array",["type"]="table"}},["bindings"]={},["callName"]="Functions.collections.tomap",["code"]="\010    local rv = {}\010    for k,v in pairs(array) do\010        rv[tostring(k)] = v\010    end\010    return rv\010",["description"]="Copy a table using tostring of each original key as the destination key. Values retain their original identities. Colliding stringified keys overwrite each other in unspecified pairs traversal order.",["kind"]="function",["line"]=42,["parameters"]={"array"},["returns"]={{["description"]="New table with stringified keys and unchanged values.",["type"]="table"}}}},["hash"]="e9ed1b575966e47176fca5fcdbde98db736f5239b9ec0bac808c8e52285892dd"},["Functions/presentation.lua"]={["bindings"]={["compareString"]={["args"]={{["description"]="RM comparison operator identifier; missing labels use the operator placeholder.",["name"]="operator",["type"]="string | nil"},{["description"]="Text or number shown before the comparison wording.",["name"]="left",["type"]="string | number"},{["description"]="Text or number shown after the comparison wording.",["name"]="right",["type"]="string | number"},{["description"]="Mark the positive wording as the primary named alternative.",["name"]="primary",["type"]="boolean | nil"}},["bindingID"]="builtin:utils.lua:compareString",["bindings"]={["operators"]="builtin:Functions/presentation.lua:operators"},["callName"]="Functions.presentation.compareString",["code"]="\010    local positive=addon.nullable(operators[operator], L[\"<operator>\"])\010    local negative=(addon.negatedOperators or {})[operator]\010    local predicate=negative and ('{{'..(primary and '!' or '')..positive..'|'..negative..'}}') or positive\010    return left .. \" \" .. predicate .. \" \" .. right\010",["description"]="Format comparison wording with named Boolean alternatives when the operator has a negative form. The primary flag marks the positive form as the primary alternative. Positive operator labels use the captured operator map; negative labels and nullable dispatch retain their live addon APIs.",["kind"]="function",["line"]=41,["namespace"]="Functions.presentation",["parameters"]={"operator","left","right","primary"},["returns"]={{["description"]="Comparison text retaining named Boolean alternative markup.",["type"]="string"}}},["nullable"]={["args"]={{["description"]="Value to display; false is preserved.",["name"]="value",["type"]="any"},{["description"]="Missing-value display text; omitted uses the localized value placeholder.",["name"]="default",["type"]="string | nil"}},["bindingID"]="builtin:utils.lua:nullable",["bindings"]={["color"]="builtin:utils.lua:color"},["callName"]="Functions.presentation.nullable",["code"]="\010    if value == nil then\010        if default ~= nil then\010            return color.RED .. default .. color.RESET\010        else\010            return color.RED .. L[\"<value>\"] .. color.RESET\010        end\010    end\010    return value\010",["compatibilityNamespaces"]={"utils"},["description"]="Return a present value unchanged, or a red display placeholder for nil. Use for readable condition labels, not as a boolean fallback.",["kind"]="function",["line"]=11,["namespace"]="Functions.presentation",["parameters"]={"value","default"},["returns"]={{["description"]="Original non-nil value, or a colored placeholder string.",["type"]="any"}}},["nullable_value"]={["args"]={{["description"]="Key to look up.",["name"]="value",["type"]="any"},{["description"]="Display lookup table.",["name"]="array",["type"]="table | nil"},{["description"]="Missing-value display text; omitted uses the localized value placeholder.",["name"]="default",["type"]="string | nil"}},["bindingID"]="builtin:utils.lua:nullable_value",["bindings"]={["color"]="builtin:utils.lua:color"},["callName"]="Functions.presentation.nullable_value",["code"]="\010    if value == nil or array == nil or type(array) ~= \"table\" then\010        if default ~= nil then\010            return color.RED .. default .. color.RESET\010        else\010            return color.RED .. L[\"<value>\"] .. color.RESET\010        end\010    end\010    return addon.nullable(array[value], default)\010",["compatibilityNamespaces"]={"utils"},["description"]="Look up a table key for display, preserving non-nil results; invalid tables, missing keys and nil keys use nullable placeholder text.",["kind"]="function",["line"]=22,["namespace"]="Functions.presentation",["parameters"]={"value","array","default"},["returns"]={{["description"]="Original non-nil lookup result, or a colored placeholder string.",["type"]="any"}}},["operators"]={["kind"]="value"},["phrase"]={["args"]={{["description"]="Localized complete sentence with named slots and optional explicit predicate alternatives.",["name"]="template",["type"]="string"},{["description"]="Identifier-keyed scalar values or typed predicates. Strings, finite numbers and booleans are supported; referenced slots must be present. Values are captured when the phrase is created.",["name"]="values",["type"]="table"}},["bindings"]={},["callName"]="Functions.presentation.phrase",["code"]="\010    return addon:CreateConditionSummaryPhrase(template, values)\010",["description"]="Create a transient named condition summary. Use {name} for scalar values and {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their percent signs, links, colors or braces. Typed predicate values participate in primary selection. Templates, values and rendered text are bounded; malformed input renders a localized unavailable summary. This changes presentation only and runs no condition observations.",["kind"]="function",["line"]=49,["namespace"]="Functions.presentation",["parameters"]={"template","values"},["returns"]={{["description"]="Transient trusted phrase recognized by condition summary rendering; do not persist it as condition data.",["type"]="RMConditionPhrase"}}},["playerize"]={["args"]={{["description"]="Unit token to compare with the literal player token.",["name"]="unit",["type"]="string | nil"},{["description"]="Value returned when unit is player.",["name"]="player",["type"]="any"},{["description"]="Value returned for every other unit.",["name"]="nonplayer",["type"]="any"}},["bindingID"]="builtin:utils.lua:playerize",["bindings"]={},["callName"]="Functions.presentation.playerize",["code"]="\010    if (unit == \"player\") then\010        return player\010    else\010        return nonplayer\010    end\010",["description"]="Choose the supplied player value only for the literal player unit token; every other unit selects the nonplayer value. Selected false and nil values are preserved.",["kind"]="function",["line"]=33,["namespace"]="Functions.presentation",["parameters"]={"unit","player","nonplayer"},["returns"]={{["description"]="The selected value, including false or nil.",["type"]="any"}}},["predicate"]={["args"]={{["description"]="Comparison operator key, such as EQUALS or LESSTHAN.",["name"]="operator",["type"]="string"},{["description"]="True marks the main comparison to negate; false or nil leaves it eligible only when no primary predicate exists.",["name"]="primary",["type"]="boolean | nil"}},["bindings"]={["operators"]="builtin:Functions/presentation.lua:operators"},["callName"]="Functions.presentation.predicate",["code"]="\010    local positive=addon.nullable(operators[operator], L[\"<operator>\"])\010    return addon:CreateConditionSummaryPredicate(positive, (addon.negatedOperators or {})[operator], primary)\010",["description"]="Create a typed comparison predicate for a named condition phrase. Positive wording uses the original captured operator map and negative wording uses the current negated operator map. A primary predicate takes precedence over qualifiers; only the first eligible predicate negates. Unknown operators use the existing operator placeholder. This formats wording without comparing values or evaluating a condition.",["kind"]="function",["line"]=53,["namespace"]="Functions.presentation",["parameters"]={"operator","primary"},["returns"]={{["description"]="Transient typed predicate used as a named phrase value; do not persist it as condition data.",["type"]="RMConditionPredicate"}}}},["hash"]="0db5215bc1d3a16b8a1f63b66539b09261dceea9750d8d7ba12f68847e9dc279"},["Functions/text.lua"]={["bindings"]={["split"]={["args"]={{["description"]="Text to split.",["name"]="inputstr",["type"]="string"},{["description"]="Lua pattern character-class separator, default %s for whitespace.",["name"]="sep",["type"]="string | nil"}},["bindingID"]="builtin:utils.lua:split",["bindings"]={["string"]="builtin:utils.lua:string"},["callName"]="Functions.text.split",["code"]="\010    if sep == nil then\010        sep = \"%s\"\010    end\010    local t={}\010    for str in string.gmatch(inputstr, \"([^\"..sep..\"]+)\") do\010        table.insert(t, str)\010    end\010    return t\010",["compatibilityNamespaces"]={"utils"},["description"]="Split a string into nonempty runs between separator characters. The separator is inserted into a Lua pattern character class; it is not a literal multi-character delimiter. Empty fields are omitted.",["kind"]="function",["line"]=9,["namespace"]="Functions.text",["parameters"]={"inputstr","sep"},["returns"]={{["description"]="Dense array of nonempty text fields.",["type"]="string[]"}}},["trim"]={["args"]={{["description"]="Text to trim.",["name"]="s",["type"]="string"}},["bindingID"]="builtin:utils.lua:trim",["bindings"]={},["callName"]="Functions.text.trim",["code"]="\010    return (s:gsub(\"^%s*(.-)%s*$\", \"%1\"))\010",["compatibilityNamespaces"]={"utils"},["description"]="Remove leading and trailing Lua-pattern whitespace from a string.",["kind"]="function",["line"]=34,["namespace"]="Functions.text",["parameters"]={"s"},["returns"]={{["description"]="Trimmed text.",["type"]="string"}}},["wrap"]={["args"]={{["description"]="Text to wrap.",["name"]="str",["type"]="string"},{["description"]="Target line width, default 72 characters.",["name"]="limit",["type"]="number | nil"}},["bindingID"]="builtin:utils.lua:wrap",["bindings"]={},["callName"]="Functions.text.wrap",["code"]="\010    limit = limit or 72\010    local here = 1\010\010    -- the \"\".. is there because :gsub returns multiple values\010    return \"\"..str:gsub(\"(%s+)()(%S+)()\",\010            function(_, st, word, fi)\010                if fi-here > limit then\010                    here = st\010                    return \"\\n\"..word\010                end\010            end)\010",["compatibilityNamespaces"]={"utils"},["description"]="Wrap text at whitespace boundaries near a target column count. Long words are retained intact.",["kind"]="function",["line"]=20,["namespace"]="Functions.text",["parameters"]={"str","limit"},["returns"]={{["description"]="Text with line breaks inserted at word boundaries.",["type"]="string"}}}},["hash"]="548287c70d5362bd78f8ba14a751742a8bdf84c6eb8ce03eed459264585e0c6f"},["Functions/values.lua"]={["bindings"]={["compare"]={["args"]={{["description"]="RM operator identifier.",["name"]="operator",["type"]="string"},{["description"]="Left operand; use numbers for ordering and divisibility.",["name"]="left",["type"]="any"},{["description"]="Right operand; DIVISIBLE requires a nonzero divisor.",["name"]="right",["type"]="any"}},["bindingID"]="builtin:utils.lua:compare",["bindings"]={},["callName"]="Functions.values.compare",["code"]="\010    if operator == \"LESSTHAN\" then\010        return left < right\010    elseif operator == \"LESSTHANOREQUALS\" then\010        return left <= right\010    elseif operator == \"GREATERTHAN\" then\010        return left > right\010    elseif operator == \"GREATERTHANOREQUALS\" then\010        return left >= right\010    elseif operator == \"EQUALS\" then\010        return left == right\010    elseif operator == \"NOTEQUALS\" then\010        return left ~= right\010    elseif operator == \"DIVISIBLE\" then\010        return (left % right) == 0\010    else\010        addon:warn(\"Invalid Operator %s\", operator)\010    end\010",["compatibilityNamespaces"]={"utils"},["description"]="Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and return nil; operands must support the selected Lua operation.",["kind"]="function",["line"]=8,["namespace"]="Functions.values",["parameters"]={"operator","left","right"},["returns"]={{["description"]="Comparison result, or nil for an unknown operator.",["type"]="boolean | nil"}}},["isin"]={["args"]={{["description"]="Table to inspect.",["name"]="array",["type"]="table"},{["description"]="Lookup key.",["name"]="value",["type"]="any"}},["bindingID"]="builtin:utils.lua:isin",["bindings"]={},["callName"]="Functions.values.isin",["code"]="\010    return array[value] ~= nil\010",["compatibilityNamespaces"]={"utils"},["description"]="Check whether a table has a non-nil value at a key. A stored false value still counts as present; this does not scan table values.",["kind"]="function",["line"]=28,["namespace"]="Functions.values",["parameters"]={"array","value"},["returns"]={{["description"]="True when array[value] is non-nil.",["type"]="boolean"}}}},["hash"]="f7b5abd612e19bed62c9576e09bc8e9d749ca4dab368a736e374f32e71568a54"},["Platform/actions.lua"]={["bindings"]={["Platform_GetSpellRangeState"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID whose range should be checked.",["name"]="id",["type"]="number"},{["description"]="Unit token, such as target; nil uses target.",["name"]="unit",["type"]="string | nil"},{["description"]="Spell-book scope: spell, pet or any.",["name"]="bank",["type"]="string"}},["bindings"]={["call"]="builtin:Platform/actions.lua:call",["findSlot"]="builtin:Platform/actions.lua:findSlot",["spellID"]="builtin:Platform/actions.lua:spellID"},["callName"]="addon.Platform:GetSpellRangeState",["code"]="\010    local valid,reason=spellID(id)\010    if not valid then return nil,reason end\010    if not self:CanReadValue(unit) or not self:CanReadValue(bank) then return nil,\"restricted-value\" end\010    if unit~=nil and (type(unit)~=\"string\" or unit==\"\") then return nil,\"invalid-unit\" end\010    if bank~=\"spell\" and bank~=\"pet\" and bank~=\"any\" then return nil,\"invalid-spell-bank\" end\010    unit=unit or \"target\"\010    local nativeRange=C_Spell and C_Spell.IsSpellInRange\010    local nativeShape=C_Spell and C_Spell.SpellHasRange\010    local slot,book,slotReason\010    local function legacySlot()\010        if not slot then slot,book,slotReason=findSlot(id,bank) end\010        return slot,slotReason\010    end\010    local hasRange,why,queriedShape\010    if type(nativeShape)==\"function\" then\010        queriedShape=true\010        hasRange,why=call(nativeShape,id)\010    elseif type(nativeRange)~=\"function\" and type(SpellHasRange)==\"function\" then\010        if not legacySlot() then return nil,slotReason end\010        queriedShape=true\010        hasRange,why=call(SpellHasRange,slot,book)\010    end\010    if why then return nil,why end\010    if hasRange~=nil then\010        if type(hasRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010        if not hasRange then return {applicable=false} end\010    elseif queriedShape then return nil,\"invalid-api-result\" end\010    local inRange\010    if type(nativeRange)==\"function\" then\010        inRange,why=call(nativeRange,id,unit)\010        if why then return nil,why end\010        if inRange~=nil and type(inRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010    else\010        if type(IsSpellInRange)~=\"function\" then return nil,\"missing-api\" end\010        if not legacySlot() then return nil,slotReason end\010        inRange,why=call(IsSpellInRange,slot,book,unit)\010        if why then return nil,why end\010        if inRange==0 then inRange=false elseif inRange==1 then inRange=true end\010        if inRange~=nil and type(inRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010    end\010    if inRange==nil then return nil,\"invalid-range-check\" end\010    return {applicable=true,inRange=inRange}\010",["description"]="Read spell-specific range for a unit using the appropriate client API or spell-book slot. A spell without a range restriction returns applicable=false; otherwise applicable=true and inRange records whether the unit is in range. Unknown or inaccessible observations return nil with a reason.",["kind"]="function",["line"]=40,["parameters"]={"self","id","unit","bank"},["returns"]={{["description"]="Range record with applicable and, when applicable, inRange; nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["call"]={["bindings"]={["platform"]="builtin:Platform/actions.lua:platform"},["code"]="\010    if type(fn)~=\"function\" then return nil,\"missing-api\" end\010    local ok,value=pcall(fn,...)\010    if not ok then return nil,\"api-error\" end\010    if not platform:CanReadValue(value) then return nil,\"restricted-value\" end\010    return value\010",["kind"]="function",["line"]=9,["parameters"]={"fn","..."}},["findSlot"]={["bindings"]={["call"]="builtin:Platform/actions.lua:call"},["code"]="\010    local pet=bank==\"pet\"\010    local slot,reason=call(FindSpellBookSlotBySpellID,id,pet)\010    if reason then return nil,nil,reason end\010    if slot==nil and bank==\"any\" then\010        pet=true;slot,reason=call(FindSpellBookSlotBySpellID,id,true)\010        if reason then return nil,nil,reason end\010    end\010    if slot==nil then return nil,nil,\"spell-not-in-book\" end\010    if type(slot)~=\"number\" or slot<1 or slot==math.huge or slot%1~=0 then return nil,nil,\"invalid-api-result\" end\010    return slot,pet and (BOOKTYPE_PET or \"pet\") or (BOOKTYPE_SPELL or \"spell\")\010",["kind"]="function",["line"]=28,["parameters"]={"id","bank"}},["platform"]={["kind"]="value"},["spellID"]={["bindings"]={["platform"]="builtin:Platform/actions.lua:platform"},["code"]="\010    if not platform:CanReadValue(id) then return nil,\"restricted-value\" end\010    if type(id)~=\"number\" or id<1 or id==math.huge or id%1~=0 then return nil,\"invalid-spell\" end\010    return true\010",["kind"]="function",["line"]=4,["parameters"]={"id"}}},["hash"]="c540aab94ba6e7907539aee2a43bd4b3008fe7b7de63cf8d4a727af80e3732a2"},["Platform/casting.lua"]={["bindings"]={["Platform_GetUnitCastObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Unit token whose current cast or channel should be observed.",["name"]="unit",["type"]="string"},{["description"]="Observation kind: cast or channel. These use different native interruptibility tuple positions.",["name"]="kind",["type"]="string"}},["bindings"]={["interruptibility"]="builtin:Platform/casting.lua:interruptibility",["remainingSeconds"]="builtin:Platform/casting.lua:remainingSeconds"},["callName"]="addon.Platform:GetUnitCastObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(kind) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if kind~='cast' and kind~='channel' then return nil,'invalid-cast-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {active=false} end\010    local fn\010    if kind=='cast' then fn=UnitCastingInfo else fn=UnitChannelInfo end\010    if type(fn)~='function' then return nil,'missing-api' end\010    -- Capture into an owned tuple table without comparing native values. The\010    -- channel flag is slot7; casting includes castID and uses slot8 instead.\010    local ok,tuple=pcall(function() return {fn(unit)} end)\010    if not ok then return nil,'api-error' end\010    local name=tuple[1]\010    if not self:CanReadValue(name) then return nil,'restricted-value' end\010    if name==nil then return {active=false} end\010    if type(name)~='string' or name=='' then return nil,'invalid-api-result' end\010    local record={active=true,name=name}\010    record.remainingSeconds,record.remainingReason=remainingSeconds(tuple[5])\010    record.interruptible,record.interruptibleReason=interruptibility(tuple[kind=='cast' and 8 or 7])\010    return record\010",["description"]="Observe a unit casting or channeling on supported readable clients. A readable inactive result returns active=false. Active records contain name and independently available remainingSeconds and interruptible fields, with remainingReason or interruptibleReason when an optional field is unavailable. Missing, failed or restricted observations return nil with a reason.",["kind"]="function",["line"]=27,["parameters"]={"self","unit","kind"},["returns"]={{["description"]="Fresh readable record with active, optional name, remainingSeconds and interruptible. Remaining time is in seconds and is clamped to zero. An unavailable optional field has its own reason; it does not invalidate a readable active name.",["type"]="table | nil"},{["description"]="Availability or query-validation reason when the whole observation is unavailable.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}},["interruptibility"]={["bindings"]={["platform"]="builtin:Platform/casting.lua:platform"},["code"]="\010    if not platform:CanReadValue(flag) then return nil,'restricted-value' end\010    if flag==nil then return nil,'interruptibility-unavailable' end\010    if type(flag)~='boolean' then return nil,'invalid-api-result' end\010    return not flag\010",["kind"]="function",["line"]=18,["parameters"]={"flag"}},["platform"]={["kind"]="value"},["remainingSeconds"]={["bindings"]={["finite"]="builtin:Platform/casting.lua:finite",["platform"]="builtin:Platform/casting.lua:platform"},["code"]="\010    if not platform:CanReadValue(ending) then return nil,'restricted-value' end\010    if ending==nil then return nil,'cast-time-unavailable' end\010    if not finite(ending) or ending<0 then return nil,'invalid-api-result' end\010    if type(GetTime)~='function' then return nil,'missing-api' end\010    local ok,now=pcall(GetTime)\010    if not ok then return nil,'api-error' end\010    if not platform:CanReadValue(now) then return nil,'restricted-value' end\010    if not finite(now) or now<0 then return nil,'invalid-api-result' end\010    return math.max(0,ending/1000-now)\010",["kind"]="function",["line"]=7,["parameters"]={"ending"}}},["hash"]="68742a0d8497fda64dff7e6e5199ced7a1b95ec36d41bf3ce8eb8cce8acf9268"},["Platform/glyphs.lua"]={["bindings"]={["Platform_GetGlyphItemInfo"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references.",["name"]="itemID",["type"]="number"},{["description"]="Optional positive class ID; nil queries the current player class under protection.",["name"]="classID",["type"]="number | nil"}},["bindings"]={["integer"]="builtin:Platform/glyphs.lua:integer"},["callName"]="addon.Platform:GetGlyphItemInfo",["code"]="\010    if not self:CanReadValue(itemID) or not self:CanReadValue(classID) then return nil,'restricted-value' end\010    if not integer(itemID,1) then return nil,'invalid-item' end\010    if classID==nil then\010        if type(UnitClass)~='function' then return nil,'missing-api' end\010        local ok,tuple=pcall(function() return {UnitClass('player')} end)\010        if not ok then return nil,'api-error' end\010        classID=tuple[3]\010        if not self:CanReadValue(classID) then return nil,'restricted-value' end\010        if classID==nil then return nil,'class-data-unavailable' end\010    end\010    if not integer(classID,1) then return nil,'invalid-class' end\010    local record,reason=self:GetItemInfoInstant(itemID)\010    if not record then return nil,reason end\010    if record.classID~=16 or record.subClassID~=classID then return nil,'invalid-glyph-item' end\010    return record\010",["description"]="Classify a numeric item as a glyph for the requested class, using guarded native item metadata. Class is optional and defaults to the readable player class. This establishes item classification only, not equipped status or an item-to-glyph-spell ID mapping.",["kind"]="function",["line"]=6,["parameters"]={"self","itemID","classID"},["returns"]={{["description"]="Readable canonical itemID/classID/subClassID record when the item is a glyph for the requested class; nil for invalid or unavailable metadata.",["type"]="table | nil"},{["description"]="Classification, validation or availability reason for a nil result.",["type"]="string | nil"}}},["Platform_GetGlyphSocketSnapshot"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={["integer"]="builtin:Platform/glyphs.lua:integer",["layout"]="builtin:Platform/glyphs.lua:layout",["socket"]="builtin:Platform/glyphs.lua:socket"},["callName"]="addon.Platform:GetGlyphSocketSnapshot",["code"]="\010    local position=layout(self:GetClientInfo())\010    if not position then return nil,'unsupported-glyph-layout' end\010    if type(GetNumGlyphSockets)~='function' then return nil,'missing-api' end\010    local ok,count=pcall(GetNumGlyphSockets)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(count) then return nil,'restricted-value' end\010    if count==nil then return nil,'glyph-data-unavailable' end\010    if not integer(count,0) or count>64 then return nil,'invalid-api-result' end\010    local fn=GetGlyphSocketInfo\010    if count>0 and type(fn)~='function' then return nil,'missing-api' end\010    local result={slots={},complete=true}\010    for index=1,count do\010        local record=socket(self,fn,index,position)\010        result.slots[index]=record\010        if record.active==nil then result.complete=false end\010    end\010    return result\010",["description"]="Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns slots and a complete flag. Each slot has active=false when known locked or empty, active=true plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and failed count queries return nil with a reason. This does not compare item names or prove exact item-to-spell identity.",["kind"]="function",["line"]=52,["parameters"]={"self"},["returns"]={{["description"]="Normalized bounded socket snapshot with slots and complete, or nil when the query is unavailable.",["type"]="table | nil"},{["description"]="Policy, validation or availability reason for a nil snapshot.",["type"]="string | nil"}}},["integer"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value>=minimum and value<math.huge and value%1==0\010",["kind"]="function",["line"]=3,["parameters"]={"value","minimum"}},["layout"]={["bindings"]={},["code"]="\010    local editions={\010        [11]={expansion=2,prefix='3.4.',last=3,base=30400,position=3},\010        [14]={expansion=3,prefix='4.4.',last=2,base=40400,position=4},\010        [19]={expansion=4,prefix='5.5.',last=4,base=50500,position=4},\010    }\010    local edition=editions[info.projectId]\010    if not edition or info.family~='progression' or info.expansion~=edition.expansion then return nil end\010    for patch=0,edition.last do\010        if info.version==edition.prefix..patch and info.interface==edition.base+patch then return edition.position end\010    end\010",["kind"]="function",["line"]=27,["parameters"]={"info"}},["socket"]={["bindings"]={["integer"]="builtin:Platform/glyphs.lua:integer"},["code"]="\010    local ok,tuple=pcall(function() return {fn(index)} end)\010    if not ok then return {slot=index,reason='api-error'} end\010    local enabled,kind,spell=tuple[1],tuple[2],tuple[position]\010    if not self:CanReadValue(enabled) or not self:CanReadValue(kind) then return {slot=index,reason='restricted-value'} end\010    if enabled==nil and kind==nil then return {slot=index,reason='glyph-socket-unavailable'} end\010    if not integer(kind,1) or enabled~=nil and type(enabled)~='boolean' then return {slot=index,reason='invalid-api-result'} end\010    if not enabled then return {slot=index,active=false} end\010    if not self:CanReadValue(spell) then return {slot=index,reason='restricted-value'} end\010    if spell==nil then return {slot=index,active=false} end\010    if not integer(spell,1) then return {slot=index,reason='invalid-api-result'} end\010    return {slot=index,active=true,spellID=spell}\010",["kind"]="function",["line"]=39,["parameters"]={"self","fn","index","position"}}},["hash"]="b842e38f8fe186592339cf81b8c45bb434a39798000c0a27f6f48de7f1180986"},["Platform/groups.lua"]={["bindings"]={["Platform_GetGroupMembership"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="True requests raid membership; false or nil requests any group membership.",["name"]="raidOnly",["type"]="boolean | nil"}},["bindings"]={},["callName"]="addon.Platform:GetGroupMembership",["code"]="\010    if not self:CanReadValue(raidOnly) then return nil,'restricted-value' end\010    if raidOnly~=nil and type(raidOnly)~='boolean' then return nil,'invalid-group-query' end\010    if self:GetClientInfo().family=='unknown' then return nil,'unsupported-client' end\010    local fn\010    if raidOnly then fn=IsInRaid else fn=IsInGroup end\010    if type(fn)~='function' then return nil,'missing-api' end\010    local ok,member=pcall(fn)\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(member) then return nil,'restricted-value' end\010    if member==nil then return nil,'group-data-unavailable' end\010    if type(member)~='boolean' then return nil,'invalid-api-result' end\010    return member\010",["description"]="Read public group membership on identified client families. Unknown clients are unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native default group category. A readable false result stays false. Missing, failed, malformed or restricted observations return nil with a reason.",["kind"]="function",["line"]=6,["parameters"]={"self","raidOnly"},["returns"]={{["description"]="Observed membership, or nil when unavailable.",["type"]="boolean | nil"},{["description"]="Validation or availability reason for a nil result.",["type"]="string | nil"}}}},["hash"]="c9a001ecc3f69a0b3769d5772e6490c4ead926b84c6feb3ffd2eca5065b20115"},["Platform/items.lua"]={["bindings"]={["Platform_GetItemInfoInstant"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Positive item ID or native-recognized item name/link to classify.",["name"]="item",["type"]="number | string"}},["bindings"]={["finite"]="builtin:Platform/items.lua:finite",["identifier"]="builtin:Platform/items.lua:identifier"},["callName"]="addon.Platform:GetItemInfoInstant",["code"]="\010    local valid,reason=identifier(item)\010    if not valid then return nil,reason end\010    local fn=C_Item and C_Item.GetItemInfoInstant\010    if type(fn)~='function' then fn=GetItemInfoInstant end\010    if type(fn)~='function' then return nil,'missing-api' end\010    local ok,tuple=pcall(function() return {fn(item)} end)\010    if not ok then return nil,'api-error' end\010    local id,class,subclass=tuple[1],tuple[6],tuple[7]\010    if not self:CanReadValue(id) or not self:CanReadValue(class) or not self:CanReadValue(subclass) then return nil,'restricted-value' end\010    if id==nil then return nil,'item-data-unavailable' end\010    if not finite(id) or id<=0 or id%1~=0 or not finite(class) or class%1~=0\010        or not finite(subclass) or subclass%1~=0 or type(item)=='number' and id~=item then return nil,'invalid-api-result' end\010    return {itemID=id,classID=class,subClassID=subclass}\010",["description"]="Read normalized native item classification metadata. The record contains canonical itemID, classID and subClassID; it does not require loaded item display text. Missing, failed, malformed or restricted metadata returns nil with a reason.",["kind"]="function",["line"]=44,["parameters"]={"self","item"},["returns"]={{["description"]="Readable canonical item classification record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Validation or availability reason for a nil result.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)==\"number\" and value==value and value>=0 and value<math.huge\010",["kind"]="function",["line"]=40,["parameters"]={"value"}},["identifier"]={["bindings"]={["platform"]="builtin:Platform/items.lua:platform"},["code"]="\010    if not platform:CanReadValue(item) then return nil,\"restricted-value\" end\010    if type(item)==\"number\" and item>0 and item<math.huge and item%1==0 then return true end\010    if type(item)==\"string\" and #item>0 and #item<=1024 then return true end\010    return nil,\"invalid-item\"\010",["kind"]="function",["line"]=3,["parameters"]={"item"}},["platform"]={["kind"]="value"}},["hash"]="fc3e3de14f06bdb589de9c99347fbd9e676c57ebcd95ae0fd6e4a7c641a4e40a"},["Platform/range.lua"]={["bindings"]={["Platform_GetNameplateMaxDistance"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"}},["bindings"]={},["callName"]="addon.Platform:GetNameplateMaxDistance",["code"]="\010    local query=C_CVar and C_CVar.GetCVar or GetCVar\010    if type(query)~='function' then return nil,'missing-api' end\010    local ok,value=pcall(query,'nameplateMaxDistance')\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(value) then return nil,'restricted-value' end\010    if type(value)~='string' and type(value)~='number' then return nil,'nameplate-distance-unavailable' end\010    local maximum=tonumber(value)\010    if not maximum or maximum~=maximum or maximum<=0 or maximum==math.huge then return nil,'nameplate-distance-unavailable' end\010    return maximum\010",["description"]="Read the current positive nameplate visibility distance using the supported CVar API. This limits a Distance Count query; it does not prove that all nearby units have been observed. Missing, malformed, restricted or failed observations return nil with a reason.",["kind"]="function",["line"]=42,["parameters"]={"self"},["returns"]={{["description"]="Current positive visibility distance in yards; nil when unavailable.",["type"]="number | nil"},{["description"]="Availability reason for a nil result.",["type"]="string | nil"}}},["Platform_GetRangeCheckBounds"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Current unit token whose distance from the player should be observed.",["name"]="unit",["type"]="string"}},["bindings"]={},["callName"]="addon.Platform:GetRangeCheckBounds",["code"]="\010    if not self:CanReadValue(unit) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if not LibStub then return nil,'missing-range-provider' end\010    local loaded,provider=pcall(function() return LibStub('LibRangeCheck-3.0',true) end)\010    if not loaded or not provider or type(provider.GetRange)~='function' then return nil,'missing-range-provider' end\010    local ok,minimum,maximum=pcall(provider.GetRange,provider,unit)\010    if not ok then return nil,'range-provider-error' end\010    if not self:CanReadValue(minimum) or not self:CanReadValue(maximum) then return nil,'restricted-value' end\010    for _,bound in pairs({minimum=minimum,maximum=maximum}) do\010        if type(bound)~='number' or bound~=bound or bound<0 or bound==math.huge then return nil,'invalid-range-result' end\010    end\010    if minimum==nil and maximum==nil then return nil,'range-unavailable' end\010    if minimum and maximum and minimum>maximum then return nil,'invalid-range-result' end\010    return {minimum=minimum,maximum=maximum}\010",["description"]="Read the public LibRangeCheck interval for a unit. A successful upper bound is inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither bound is an exact distance, and a missing upper bound is not proof that the unit is outside every radius. Unavailable, malformed, restricted or failed observations return nil with a reason.",["kind"]="function",["line"]=56,["parameters"]={"self","unit"},["returns"]={{["description"]="Readable interval with optional minimum and maximum bounds in yards. At least one bound is present; nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason for a nil result.",["type"]="string | nil"}}}},["hash"]="694ad01a2e8aaa0a140b1cc1f78715033605cf7f5f6e105c8b72f9439737c55e"},["Platform/spells.lua"]={["bindings"]={["Platform_GetSpellCharges"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose charges should be read.",["name"]="spell",["type"]="number | string"}},["bindings"]={["copy"]="builtin:Platform/spells.lua:copy",["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:GetSpellCharges",["code"]="\010    local valid,reason=identifier(spell)\010    if not valid then return nil,reason end\010    local ok,record\010    if C_Spell and type(C_Spell.GetSpellCharges)==\"function\" then\010        ok,record=pcall(C_Spell.GetSpellCharges,spell)\010    elseif type(GetSpellCharges)==\"function\" then\010        local current,maximum,start,duration,rate\010        ok,current,maximum,start,duration,rate=pcall(GetSpellCharges,spell)\010        if not ok then return nil,\"api-error\" end\010        record={currentCharges=current,maxCharges=maximum,cooldownStartTime=start,cooldownDuration=duration,chargeModRate=rate}\010    else return nil,\"missing-api\" end\010    if not ok then return nil,\"api-error\" end\010    if not self:CanReadValue(record) then return nil,\"restricted-value\" end\010    if record==nil then return nil,\"spell-charges-unavailable\" end\010    local charges,why=copy(record,{currentCharges=\"number\",maxCharges=\"number\",cooldownStartTime=\"number\",\010        cooldownDuration=\"number\",chargeModRate=\"number\",isActive=\"boolean\"})\010    if not charges then return nil,why end\010    if next(charges)==nil then return nil,\"spell-charges-unavailable\" end\010    local current,maximum,start,duration=charges.currentCharges,charges.maxCharges,charges.cooldownStartTime,charges.cooldownDuration\010    if current==nil or maximum==nil or start==nil or duration==nil or current<0 or current%1~=0\010        or maximum<1 or maximum%1~=0 or current>maximum or start<0 or duration<0\010        or charges.chargeModRate and charges.chargeModRate<=0 then return nil,\"invalid-api-result\" end\010    local active=current<maximum and start>0 and duration>0\010    if charges.isActive==nil then charges.isActive=active\010    elseif charges.isActive and not active then return nil,\"invalid-api-result\" end\010    charges.chargeModRate=charges.chargeModRate or 1\010    return charges\010",["description"]="Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason.",["kind"]="function",["line"]=160,["parameters"]={"self","spell"},["returns"]={{["description"]="Readable charge record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["Platform_GetSpellCooldown"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose cooldown should be read.",["name"]="spell",["type"]="number | string"}},["bindings"]={["copy"]="builtin:Platform/spells.lua:copy",["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:GetSpellCooldown",["code"]="\010    local valid, reason = identifier(spell)\010    if not valid then return nil, reason end\010    local ok, record\010    if C_Spell and type(C_Spell.GetSpellCooldown) == \"function\" then\010        ok, record = pcall(C_Spell.GetSpellCooldown, spell)\010    elseif type(GetSpellCooldown) == \"function\" then\010        local start, duration, enabled, rate\010        ok, start, duration, enabled, rate = pcall(GetSpellCooldown, spell)\010        if not ok then return nil, \"api-error\" end\010        for _, value in pairs({start=start, duration=duration, enabled=enabled, rate=rate}) do\010            if not self:CanReadValue(value) then return nil, \"restricted-value\" end\010        end\010        if start ~= nil then\010            if enabled ~= 0 and enabled ~= 1 then return nil, \"invalid-api-result\" end\010            record = {startTime=start, duration=duration, isEnabled=enabled == 1, modRate=rate or 1}\010        end\010    else return nil, \"missing-api\" end\010    if not ok then return nil, \"api-error\" end\010    if not self:CanReadValue(record) then return nil, \"restricted-value\" end\010    if record == nil then return nil, \"spell-data-unavailable\" end\010    local cooldown, why = copy(record, {startTime=\"number\", duration=\"number\", isEnabled=\"boolean\", modRate=\"number\"})\010    if not cooldown then return nil, why end\010    if cooldown.startTime == nil or cooldown.duration == nil or cooldown.isEnabled == nil\010        or cooldown.startTime < 0 or cooldown.duration < 0 or (cooldown.modRate and cooldown.modRate <= 0) then\010        return nil, \"invalid-api-result\"\010    end\010    cooldown.modRate = cooldown.modRate or 1\010    return cooldown\010",["description"]="Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate.",["kind"]="function",["line"]=87,["parameters"]={"self","spell"},["returns"]={{["description"]="Readable cooldown record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["Platform_IsAutoRepeatActive"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Positive integer spell ID, not a spell-book slot.",["name"]="spellID",["type"]="number"}},["bindings"]={["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:IsAutoRepeatActive",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    local valid,reason=identifier(spellID,true)\010    if not valid then return nil,reason end\010    local native=C_Spell and C_Spell.IsAutoRepeatSpell\010    local ok,active\010    if type(native)=='function' then\010        ok,active=pcall(native,spellID)\010    else\010        if type(IsAutoRepeatSpell)~='function' or type(FindSpellBookSlotBySpellID)~='function' then return nil,'missing-api' end\010        local found,slot=pcall(FindSpellBookSlotBySpellID,spellID,false)\010        if not found then return nil,'api-error' end\010        if not self:CanReadValue(slot) then return nil,'restricted-value' end\010        if slot==nil then return nil,'spell-not-in-book' end\010        if type(slot)~='number' or slot<1 or slot==math.huge or slot%1~=0 then return nil,'invalid-api-result' end\010        ok,active=pcall(IsAutoRepeatSpell,slot,BOOKTYPE_SPELL or 'spell')\010    end\010    if not ok then return nil,'api-error' end\010    if not self:CanReadValue(active) then return nil,'restricted-value' end\010    if type(native)~='function' then\010        if active==0 then active=false elseif active==1 then active=true end\010    end\010    if type(active)~='boolean' then return nil,'invalid-api-result' end\010    return active\010",["description"]="Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This is distinct from a current or queued cast. Modern clients receive the exact spell ID; a legacy query resolves the player spell-book slot first. Restricted client policies, unreadable results and unavailable book slots return nil with a reason. This observes state and never starts or stops a spell.",["kind"]="function",["line"]=209,["parameters"]={"self","spellID"},["returns"]={{["description"]="True when the client reports this spell auto-repeating; false when it reports inactive; nil when unavailable.",["type"]="boolean | nil"},{["description"]="Validation or availability reason for a nil result.",["type"]="string | nil"}}},["Platform_IsSpellReady"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose cooldown should be checked.",["name"]="spell",["type"]="number | string"},{["description"]="Current evaluation time in seconds from GetTime(), normally evalStart.",["name"]="now",["type"]="number"}},["bindings"]={},["callName"]="addon.Platform:IsSpellReady",["code"]="\010    if not self:CanReadValue(now) then return nil, \"restricted-value\" end\010    if type(now)~=\"number\" or now~=now or now==math.huge or now==-math.huge then\010        return nil, \"invalid-time\"\010    end\010    local cooldown,reason=self:GetSpellCooldown(spell)\010    if not cooldown then return nil,reason end\010    if not cooldown.isEnabled then return false end\010    local expires=cooldown.startTime+cooldown.duration\010    if cooldown.duration==0 or expires<=now then return true end\010\010    local gcd,why=self:GetGlobalCooldown()\010    if not gcd then return nil,why end\010    if not gcd.isEnabled or gcd.duration==0 then return false end\010    -- modRate controls cooldown animation; API timestamps/duration already\010    -- describe expiration in GetTime seconds, so do not divide them by it.\010    local gcdExpires=gcd.startTime+gcd.duration\010    return gcdExpires>now and expires<=gcdExpires+0.001\010",["description"]="Check whether a spell can be recommended now, allowing a spell whose remaining cooldown ends with the current global cooldown. This checks cooldown readiness only; it does not check learned status, range or resource usability. Pass evaluation time from evalStart or GetTime().",["kind"]="function",["line"]=140,["parameters"]={"self","spell","now"},["returns"]={{["description"]="True when ready by the end of the global cooldown; false when its own cooldown prevents recommendation; nil when the client cannot supply a readable result.",["type"]="boolean | nil"},{["description"]="Availability or validation reason when the result is nil.",["type"]="string | nil"}}},["copy"]={["bindings"]={["platform"]="builtin:Platform/spells.lua:platform"},["code"]="\010    if not platform:CanReadValue(record) then return nil, \"restricted-value\" end\010    if type(record) ~= \"table\" then return nil, \"invalid-api-result\" end\010    local result = {}\010    for key, kind in pairs(fields) do\010        local value = record[key]\010        if not platform:CanReadValue(value) then return nil, \"restricted-value\" end\010        if value ~= nil then\010            if type(value) ~= kind and not (kind == \"icon\" and (type(value) == \"number\" or type(value) == \"string\")) then\010                return nil, \"invalid-api-result\"\010            end\010            if type(value) == \"number\" and (value ~= value or value == math.huge or value == -math.huge) then\010                return nil, \"invalid-api-result\"\010            end\010            result[key] = value\010        end\010    end\010    return result\010",["kind"]="function",["line"]=11,["parameters"]={"record","fields"}},["identifier"]={["bindings"]={["platform"]="builtin:Platform/spells.lua:platform"},["code"]="\010    if not platform:CanReadValue(value) then return false, \"restricted-value\" end\010    if type(value) == \"number\" and value > 0 and value < math.huge and value % 1 == 0 then return true end\010    if not idOnly and type(value) == \"string\" and #value > 0 then return true end\010    return false, \"invalid-spell\"\010",["kind"]="function",["line"]=4,["parameters"]={"value","idOnly"}},["platform"]={["kind"]="value"}},["hash"]="5949b51dfd644e8e4ba37e8da81726d7a7c1aca1382d4d7ef9e99a8f6314185e"},["Platform/unit_health.lua"]={["bindings"]={["Platform_GetUnitHealthObservation"]={["args"]={{["description"]="Rotation Master platform adapter (implicit with colon calls).",["name"]="self",["type"]="RMPlatform"},{["description"]="Unit token whose current health should be observed.",["name"]="unit",["type"]="string"},{["description"]="True also observes maximum health; false or nil reads current health only.",["name"]="includeMaximum",["type"]="boolean | nil"}},["bindings"]={["finite"]="builtin:Platform/unit_health.lua:finite"},["callName"]="addon.Platform:GetUnitHealthObservation",["code"]="\010    if self:GetClientInfo().combatDataPolicy~='probe' then return nil,'unsupported-policy' end\010    if not self:CanReadValue(unit) or not self:CanReadValue(includeMaximum) then return nil,'restricted-value' end\010    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end\010    if includeMaximum~=nil and type(includeMaximum)~='boolean' then return nil,'invalid-health-query' end\010    if type(UnitExists)~='function' then return nil,'missing-api' end\010    local existsOk,exists=pcall(UnitExists,unit)\010    if not existsOk then return nil,'api-error' end\010    if not self:CanReadValue(exists) then return nil,'restricted-value' end\010    if exists==nil then return nil,'unit-data-unavailable' end\010    if type(exists)~='boolean' then return nil,'invalid-api-result' end\010    if not exists then return {exists=false} end\010    if type(UnitHealth)~='function' then return nil,'missing-api' end\010    local currentOk,current=pcall(UnitHealth,unit)\010    if not currentOk then return nil,'api-error' end\010    if not self:CanReadValue(current) then return nil,'restricted-value' end\010    -- Keep the native proof visible at the arithmetic boundary; the platform\010    -- guard above also covers older clients and the issecretvalue predicate.\010    if canaccessvalue and not canaccessvalue(current) then return nil,'restricted-value' end\010    if current==nil then return nil,'health-data-unavailable' end\010    if not finite(current) or current<0 then return nil,'invalid-api-result' end\010    local record={exists=true,current=current}\010    if includeMaximum then\010        if type(UnitHealthMax)~='function' then return nil,'missing-api' end\010        local maximumOk,maximum=pcall(UnitHealthMax,unit)\010        if not maximumOk then return nil,'api-error' end\010        if not self:CanReadValue(maximum) then return nil,'restricted-value' end\010        if canaccessvalue and not canaccessvalue(maximum) then return nil,'restricted-value' end\010        if maximum==nil then return nil,'health-data-unavailable' end\010        if not finite(maximum) or maximum<0 then return nil,'invalid-api-result' end\010        record.maximum=maximum\010    end\010    return record\010",["description"]="Observe readable current health and optionally maximum health on supported clients. A readable absent unit returns exists=false. Missing, failed, restricted or malformed observations return nil with a reason; they do not establish an absent unit or a health value.",["kind"]="function",["line"]=10,["parameters"]={"self","unit","includeMaximum"},["returns"]={{["description"]="Fresh readable record with exists and, when present, current health. Maximum health is included only when requested.",["type"]="table | nil"},{["description"]="Policy, validation or availability reason for a nil health observation.",["type"]="string | nil"}}},["finite"]={["bindings"]={},["code"]="\010    return type(value)=='number' and value==value and value<math.huge and value>-math.huge\010",["kind"]="function",["line"]=4,["parameters"]={"value"}}},["hash"]="dc2ecdf6855609a696d449494ee131246edf21fc63d4cfcbb73938602c5e15a9"},["UI/checkbox.lua"]={["bindings"]={["AceGUI"]={["kind"]="value"},["CreateConditionCheckBox"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/checkbox.lua:constructor"},["callName"]="addon:CreateConditionCheckBox",["code"]="\010    local widget=addon:AcquireConditionWidget('RM-CheckBox',constructor)\010    ---@cast widget RMConditionCheckBox\010    return widget\010",["description"]="Create a native boolean condition control. Configure SetLabel, SetValue, SetDisabled and OnValueChanged; add it with parent:AddChild(widget).",["kind"]="function",["line"]=28,["parameters"]={"self"},["returns"]={{["description"]="Checkbox widget with boolean value and callback methods.",["type"]="RMConditionCheckBox"}}},["constructor"]={["bindings"]={},["code"]="\010    local w={type='RM-CheckBox',alive=false,disabled=false}\010    local frame=CreateFrame('Frame',nil,UIParent);w.frame=frame;frame:SetSize(180,24)\010    local button=addon:CreateWorkbenchCheckBox(frame,'',180);w.button=button;button:SetAllPoints(frame)\010    function w:OnAcquire() self.alive=true;self:SetLabel('');self:SetValue(false);self:SetDisabled(false);self:SetWidth(180);self:SetHeight(24) end\010    function w:OnRelease() self.alive=false;self:SetValue(false) end\010    function w:SetLabel(text) button:SetText(text or '') end\010    function w:SetValue(value) button:SetChecked(value==true) end\010    function w:GetValue() return button:GetChecked() end\010    function w:SetDisabled(value) self.disabled=value==true;if self.disabled then button:Disable();button:SetAlpha(.45) else button:Enable();button:SetAlpha(1) end end\010    function w:OnWidthSet(width) button:GetFontString():SetWidth(math.max(1,width-22)) end\010    addon:SetUIScript(button,'OnClick',function()\010        if not w.alive or w.disabled then return end\010        w:SetValue(not w:GetValue());w:Fire('OnValueChanged',w:GetValue())\010    end)\010    ---@cast w AceGUIWidget\010    return addon:RegisterConditionWidget(w,1,legacy)\010",["kind"]="function",["line"]=9,["parameters"]={"legacy"}}},["hash"]="ed21f7564454391cadc13b4846537877603dc684c214aa547b8bb76419dcf609"},["UI/condition_display.lua"]={["bindings"]={["CreateConditionButton"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["buttonConstructor"]="builtin:UI/condition_display.lua:buttonConstructor"},["callName"]="addon:CreateConditionButton",["code"]=" return self:AcquireConditionWidget('RM-ConditionButton',buttonConstructor) ",["description"]="Create a native button using the shared condition widget lifecycle and workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction; OnClick receives the mouse button. Add it to the supplied parent.",["kind"]="function",["line"]=120,["parameters"]={"self"},["returns"]={{["description"]="Native button with label, disabled state and lease-protected callbacks.",["type"]="RMConditionButton"}}},["CreateConditionLabel"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["labelConstructor"]="builtin:UI/condition_display.lua:labelConstructor"},["callName"]="addon:CreateConditionLabel",["code"]=" return self:AcquireConditionWidget('RM-ConditionLabel',labelConstructor) ",["description"]="Create native wrapping text that measures its height from its width and font. SetText, SetFont or SetFontObject configure its contents. Add it to the supplied parent so layout can track its measured height.",["kind"]="function",["line"]=118,["parameters"]={"self"},["returns"]={{["description"]="Native wrapping text control with font, color and alignment meth