  function w:SetImageSize(width,height) self.imageWidth,self.imageHeight=width,height;image:SetSize(width,height);measure() end\010        function w:SetDisabled(value) self.disabled=value==true;if self.disabled then frame:Disable() else frame:Enable() end end\010    end\010    function w:OnAcquire()\010        self.measuring=false;self.measuredHeight=nil\010        if interactive then self.imagePath=nil;self.imageWidth,self.imageHeight=24,24;image:SetTexture(nil);image:SetSize(24,24);image:Hide();self:SetDisabled(false) end\010        self:SetText('');self:SetFontObject();self:SetColor();self:SetJustifyH('LEFT');self:SetJustifyV('TOP');self:SetWidth(200)\010        if interactive then\010            frame:RegisterForClicks('LeftButtonUp','RightButtonUp');local lease=self.rmLease\010            local function live() return w.rmActive and w.rmLease==lease and not w:IsReleasing() end\010            addon:SetUIScript(frame,'OnEnter',function() if live() then w:Fire('OnEnter') end end)\010            addon:SetUIScript(frame,'OnLeave',function() if live() then w:Fire('OnLeave') end end)\010            addon:SetUIScript(frame,'OnClick',function(_,button) if live() and not w.disabled then w:Fire('OnClick',button) end end)\010        end\010    end\010    function w:OnRelease()\010        self.text='';self.measuring=false;self.measuredHeight=nil;label:SetText('')\010        if image then image:Hide();image:SetTexture(nil);self.imagePath=nil;if GameTooltip and GameTooltip:IsOwned(frame) then GameTooltip:Hide() end end\010    end\010    return addon:RegisterConditionWidget(w,1,legacy)\010",["kind"]="function",["line"]=13,["parameters"]={"legacy","interactive"}}},["hash"]="9afd55873787bf6b9975724b7edfd3f9565e1267d2eb864f8bd382bf1855793f"},["UI/condition_icon.lua"]={["bindings"]={["CreateConditionIcon"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["constructor"]="builtin:UI/conditio