f not finite(value) then return tostring(value) end\010        return string.format('%.6g',value*(w.isPercent and 100 or 1))..(w.isPercent and '%' or '')\010    end\010    local function parse(text)\010        text=text:match('^%s*(.-)%s*$')\010        if w.isPercent and text:sub(-1)=='%' then text=text:sub(1,-2) end\010        local value=tonumber(text)\010        if not finite(value) then return end\010        if w.isPercent then value=value/100 end\010        if value<w.minimum or value>w.maximum then return end\010        return value\010    end\010    local function paint()\010        w.setting=true;input:SetText(display());w.confirmed=input:GetText();w.pending=false\010        input:SetTextColor(1,1,1)\010        if slider then slider:SetValue(finite(w.value) and w.value or w.minimum) end\010        w.setting=false\010    end\010    local function pendingChanged() w:Fire('OnPendingChanged',w.pending) end\010    function w:SetLabel(text)\010        self.label=text or '';caption:SetText(self.label);local y=self.label~='' and -20 or 0\010        if self.label~='' then caption:Show() else caption:Hide() end\010        input:ClearAllPoints();input:SetPoint('TOPRIGHT',0,y);input:SetHeight(24)\010        if slider then\010            input:SetWidth(64);slider:ClearAllPoints();slider:SetPoint('LEFT',frame,'LEFT',0,y/2);slider:SetPoint('RIGHT',input,'LEFT',-8,0)\010        else input:SetPoint('TOPLEFT',0,y) end\010        self:SetHeight(self.label~='' and 44 or 24)\010    end\010    function w:SetText(text) self.text=text==nil and '' or tostring(text);paint() end\010    function w:GetText() return input:GetText() end\010    function w:SetValue(value) self.value=value;paint() end\010    function w:GetValue() return self.value end\010    function w:SetSliderValues(minimum,maximum,step)\010        if not finite(minimum) or not finite(maximum) or maximum<minimum or not finite(step) or step<=0 then return end\010        self.minimum,self.maximum,self.step=minimum,maximum,step\010        self.setting=true;slider:SetMinMaxValues(minimum,maximum);slider:SetValueStep(step);self.setting=false;paint()\010    end\010    function w:SetIsPercent(value) self.isPercent=value==true;paint() end\010    function w:IsPending() return self.alive and not self.disabled and self.pending==true end\010    function w:CommitPending()\010        local owner=self\010        for _=1,128 do\010            if not owner then break end\010            if owner.isQueuedForRelease then return true end\010            owner=owner.parent\010        end\010        if not self:IsPending() then return true end\010        local text=input:GetText();local value=numeric and parse(text) or text\010        if numeric and not finite(value) then input:SetTextColor(1,.35,.35);return nil end\010        local changed=numeric and value~=self.value or not numeric and text~=self.text\010        if numeric then self.value=value else self.text=text end\010        paint()\010        if changed then self:Fire(numeric and 'OnValueChanged' or 'OnEnterPressed',value) end\010        pendingChanged();return true\010    end\010    function w:SetFocus() if self.alive and not self.disabled then input:SetFocus() end end\010    function w:ClearFocus() input:ClearFocus() end\010    function w:SetMaxLetters(value) input:SetMaxLetters(value) end\010    function w:DisableButton() end\010    function w:SetDisabled(value)\010        self.disabled=value==true\010        input:EnableMouse(not self.disabled);input:EnableKeyboard(not self.disabled)\010        if slider then slider:EnableMouse(not self.disabled) end\010        frame:SetAlpha(self.disabled and .45 or 1)\010        if self.disabled then paint();input:ClearFocus() end\010    end\010    function w:OnAcquire()\010        self.alive=true;self.minimum,self.maximum,self.step=0,100,1;self.isPercent=false;self.value=nil;self.text=''\010        self:SetMaxLetters(4096);self:SetWidth(220);self:SetLabel('');self:SetDisabled(false)\010        if slider then self:SetSliderValues(0,100,1) end;paint()\010    end\010    function w:OnRelease() self.alive=false;self.pending=false;input:ClearFocus() end\010    addon:SetUIScript(input,'OnTextChanged',function(_,user)\010        if w.setting or not user or not w.alive or w.disabled then return end\010        w.pending=input:GetText()~=w.confirmed\010        local valid=not numeric or parse(input:GetText())~=nil\010        input:SetTextColor(1,valid and 1 or .35,valid and 1 or .35);pendingChanged()\010    end)\010    addon:SetUIScript(input,'OnEnterPressed',function() if w.alive and not w.disabled and w:CommitPending() then input:ClearFocus() end end)\010    addon:SetUIScript(input,'OnEditFocusLost',function() if w.alive and not w.disabled and not w.isQueuedForRelease then w:CommitPending() end end)\010    addon:SetUIScript(input,'OnEscapePressed',function() if w.alive then paint();input:ClearFocus();pendingChanged() end end)\010    -- Legacy reference popups can temporarily hide their editor. Only release\010    -- discards pending input; ordinary hiding must retain invalid blockers too.\010    addon:SetUIScript(frame,'OnHide',function() input:ClearFocus() end)\010    if slider then\010        slider:EnableMouseWheel(true)\010        addon:SetUIScript(slider,'OnValueChanged',function(_,value)\010            if w.setting or not w.alive or w.disabled or not finite(value) then return end\010            value=math.max(w.minimum,math.min(w.maximum,w.minimum+math.floor((value-w.minimum)/w.step+.5)*w.step))\010            local changed=value~=w.value;w.value=value;paint()\010            if changed then w:Fire('OnValueChanged',value) end;pendingChanged()\010        end)\010        addon:SetUIScript(slider,'OnMouseWheel',function(_,direction)\010            if w.alive and not w.disabled and direction~=0 then slider:SetValue((finite(w.value) and w.value or w.minimum)+(direction>0 and w.step or -w.step)) end\010        end)\010    end\010    ---@cast w AceGUIWidget\010    return addon:Reg