se;self:DoLayout() end\010    function group:OnWidthSet() if not self.sizing then self:DoLayout() end end\010    function group:SetWidth(width)\010        self.sizing=true;frame:SetWidth(width);frame.width=width;self.sizing=false;self:DoLayout()\010    end\010    function group:LayoutFinished(_,height) self:SetHeight(height or 1) end\010    function group:AddChild(child)\010        self.children[#self.children+1]=child;child.parent=self\010        if child.frame then child.frame:SetParent(frame);child.frame:Show() end\010        self:DoLayout()\010    end\010    function group:AddChildren(...) for i=1,select('#',...) do self:AddChild(select(i,...)) end end\010    function group:ReleaseChildren()\010        local children=self.children;self.children={}\010        local problem\010        for _,child in ipairs(children) do local ok,why=pcall(addon.ReleaseConditionWidget,addon,child);child.parent=nil;if not ok then problem=problem or why end end\010        if problem then error(problem,0) end\010        self:DoLayout()\010    end\010    function group:DoLayout()\010        if self.paused or self.layingOut or self.isQueuedForRelease then return end\010        self.layingOut=true\010        local width=math.max(1,frame:GetWidth() or 300);local padding=self:GetUserData('padding')\010        padding=type(padding)=='number' and padding==padding and math.max(0,math.min(64,padding)) or 0\010        width=math.max(1,width-padding*2);local y=padding;local gap=4\010        local settings=self:GetUserData('table');local columns=self.layout=='Table' and settings and settings.columns\010        local compatibility=self.layout~='List' and self.layout~='Table' and self.layout~='RM-SpellField'\010        if self.layout=='Table' and settings and (settings.align or settings.alignH or settings.alignV or settings.space~=nil or settings.spaceH~=nil or settings.spaceV~=nil) then compatibility=true end\010        if columns then for _,column in ipairs(columns) do if type(column)~='number' then compatibility=true end end end\010        for _,child in ipairs(self.children) do local cell=child:GetUserData('cell');if cell and (cell.colspan or cell.rowspan or cell.align or cell.alignH or cell.alignV and (self.layout~='Table' or verticalAlignment(cell.alignV)==nil)) then compatibility=true end end\010        local legacy=compatibility and AceGUI.GetLayout and AceGUI:GetLayout(self.layout)\010        if legacy then\010            -- Saved custom callbacks can still request Ace layouts and advanced\010            -- table cells. Retain that explicit compatibility path while RM's\010            -- ordinary built-in groups own their geometry here.\010            legacy(frame,self.children);self.layingOut=false\010            if self.parent and self.parent.DoLayout then self.parent:DoLayout() end\010            return\010        elseif self.layout=='RM-SpellField' then\010            y=addon:LayoutWorkbenchSpellGroup(frame,self.children) or 0\010        else\010            local widths\010            if columns and #columns>0 then\010                widths={};local fixed,weight=gap*(#columns-1),0\010                for i,column in ipairs(columns) do\010                    if type(column)=='number' and column<=0 then\010                        local measured=0\010                        for index=i,#self.children,#columns do local child=self.children[index];local size=type(child.width)=='number' and child.width or child.frame and child.frame:GetWidth() or 0;measured=math.max(measured,size) end\010                        widths[i]=measured;fixed=fixed+measured\010                    elseif type(column)=='number' and column<1 then widths[i]=width*column;fixed=fixed+widths[i]\010                    elseif type(column)=='number' and column>=10 then widths[i]=column;fixed=fixed+column\010                    else weight=weight+(type(column)=='number' and column or 1) end\010                end\010                for i,column in ipairs(columns) do if not widths[i] then widths[i]=math.max(1,(width-fixed)*(type(column)=='number' and column or 1)/math.max(1,weight)) end end\010            end\010            local x,rowHeight,column=padding,0,1\010            local row={}\010            local function finishRow()\010                for _,entry in ipairs(row) do\010                    entry.control:ClearAllPoints();entry.control:SetPoint('TOPLEFT',frame,'TOPLEFT',entry.x,-y-(rowHeight-entry.height)*entry.align)\010                end\010                y=y+rowHeight+gap;x,rowHeight,column=padding,0,1;row={}\010            end\010            for _,child in ipairs(self.children) do\010                local control=child.frame\010                if control then\010                    local childWidth=widths and widths[column] or (child.width=='fill' or child.fullWidth) and width or child.width=='relative' and width*(child.relWidth or 1) or child.width or control:GetWidth()\010                    if type(childWidth)~='number' then childWidth=width end\010                    child:SetWidth(math.max(1,childWidth));if child.DoLayout and child.type~='RM-ConditionGroup' then child:DoLayout() end\010                    local height=control:GetHeight() or child.height or 0;rowHeight=math.max(rowHeight,height)\010                    local cell=child:GetUserData('cell')\010                    row[#row+1]={control=control,x=x,height=height,align=widths and cell and verticalAlignment(cell.alignV) or 0}\010                    if widths and column<#widths then x=x+widths[column]+gap;column=column+1\010                    else finishRow() end\010                end\010            end\010            if #row>0 then finishRow() end\010            y=math.max(1,y-gap+padding)\010        end\010        self:LayoutFinished(width,y);self.layingOut=false\010        if self.parent and self.parent.DoLayout then self.parent:DoLayout() end\010    end\010    ---@cast group AceGUIWidget\010    return addon:RegisterConditionWidget(group,1,legacy)\010",["kind"]="function